using Htt.Infrastructure;
using static Htt.Host.Api.Sales.SalesSupport;
using Htt.Host.Api.Sales;
using Htt.SharedKernel;
using NpgsqlTypes;
using static Htt.Host.Api.MasterData.MasterDataSupport;
namespace Htt.Host.Api.MasterData;
public sealed record BusinessPreferencesInput(int SalesTermsDays,int PurchaseTermsDays,int QuoteValidDays,string DefaultDispatchMode,string Notes="");
public sealed record NumberingInput(string Prefix,long NextValue);
public sealed record BarcodeStatusInput(bool Active);
public sealed record BarcodeInput(Guid ProductUnitId,string Barcode,bool Active=true);
internal static class DiscoverySettingsEndpoints
{
    private static string Query(string? q){var x=q?.Trim()??"";Check.That(x.Length<=100,"q","Search text must be at most 100 characters.");return x;}
    private static string Order(string? sort,bool desc,IReadOnlyDictionary<string,string> names){var key=sort??names.Keys.First();Check.That(names.ContainsKey(key),"sort","Unsupported sort field.");return names[key]+(desc?" DESC":" ASC")+",id";}
    internal static async Task<int> DefaultTerms(CompanySession s,bool supplier,CancellationToken ct)=>Convert.ToInt32((await One(s,"SELECT sales_terms_days,purchase_terms_days FROM core.business_preferences WHERE company_id=@company",ct))[supplier?"purchase_terms_days":"sales_terms_days"]);
    public static void Map(RouteGroupBuilder g)
    {
        g.MapGet("/search/customers",async(string? q,string? status,string? sort,bool? descending,int? page,int? pageSize,HttpContext h,CompanySession s,CancellationToken ct)=>
        {
            var text=Query(q);if(status is not null)Check.OneOf(status,"status","ACTIVE","ON_HOLD","INACTIVE");var a=Access(h);var(offset,size)=Page(page,pageSize);var order=Order(sort,descending??false,new Dictionary<string,string>{{"code","code"},{"name","legal_name"}});
            var rows=await Read(s,$"SELECT c.id,c.code,c.status,p.legal_name,p.abn FROM crm.customers c JOIN crm.parties p ON p.company_id=c.company_id AND p.id=c.party_id WHERE c.company_id=@company AND (@status IS NULL OR c.status=@status) AND (@q='' OR strpos(lower(c.code||' '||p.legal_name||' '||coalesce(p.abn,'')),lower(@q))>0 OR EXISTS(SELECT 1 FROM crm.customer_branches cb WHERE cb.company_id=c.company_id AND cb.customer_id=c.id AND strpos(lower(cb.code||' '||cb.name||' '||cb.address_line1||' '||coalesce(cb.suburb,'')||' '||coalesce(cb.postcode,'')),lower(@q))>0) OR EXISTS(SELECT 1 FROM crm.contacts cc WHERE cc.company_id=c.company_id AND cc.party_id=c.party_id AND strpos(lower(cc.name||' '||coalesce(cc.email,'')||' '||coalesce(cc.phone,'')||' '||coalesce(cc.mobile,'')),lower(@q))>0)) AND (@all OR EXISTS(SELECT 1 FROM identity.customer_assignments ca WHERE ca.company_id=c.company_id AND ca.customer_id=c.id AND ca.membership_id=@member)) ORDER BY {order} LIMIT @size OFFSET @offset",ct,new DbArg("q",text),new DbArg("status",status,NpgsqlDbType.Text),new DbArg("all",a.Has("customers.all")),new DbArg("member",a.MembershipId),new DbArg("size",size),new DbArg("offset",offset));return Results.Ok(new{items=rows.Select(PublicRow),page=page??1,pageSize=size});
        }).WithMetadata(new Permission("customers.read"));
        foreach(var kind in new[]{"branches","contacts"})
        {
            var resource=kind;g.MapGet("/search/"+resource,async(string? q,Guid? customerId,int? page,int? pageSize,HttpContext h,CompanySession s,CancellationToken ct)=>
            {
                var text=Query(q);if(customerId is{}id)await Customer(h,s,id,ct);var a=Access(h);var(offset,size)=Page(page,pageSize);var table=resource=="branches"?"crm.customer_branches x":"crm.contacts x";var join=resource=="branches"?"x.customer_id=c.id":"x.party_id=c.party_id";var fields=resource=="branches"?"x.id,x.customer_id,x.code,x.name,x.address_line1,x.suburb,x.state,x.postcode,x.active":"x.id,c.id AS customer_id,x.name,x.email,x.phone,x.mobile,x.job_title,x.is_accounting,x.active";var match=resource=="branches"?"x.code||' '||x.name||' '||x.address_line1||' '||coalesce(x.suburb,'')||' '||coalesce(x.postcode,'')":"x.name||' '||coalesce(x.email,'')||' '||coalesce(x.phone,'')||' '||coalesce(x.mobile,'')";
                var rows=await Read(s,$"SELECT {fields} FROM {table} JOIN crm.customers c ON c.company_id=x.company_id AND {join} WHERE x.company_id=@company AND (@customer IS NULL OR c.id=@customer) AND (@q='' OR strpos(lower({match}),lower(@q))>0) AND (@all OR EXISTS(SELECT 1 FROM identity.customer_assignments ca WHERE ca.company_id=c.company_id AND ca.customer_id=c.id AND ca.membership_id=@member)) ORDER BY x.name,x.id LIMIT @size OFFSET @offset",ct,new DbArg("q",text),new DbArg("customer",customerId,NpgsqlDbType.Uuid),new DbArg("all",a.Has("customers.all")),new DbArg("member",a.MembershipId),new DbArg("size",size),new DbArg("offset",offset));return Results.Ok(new{items=rows.Select(PublicRow),page=page??1,pageSize=size});
            }).WithMetadata(new Permission("customers.read"));
        }
        g.MapGet("/search/products",Products).WithMetadata(new Permission("catalog.read"));
        g.MapGet("/customers/{customerId:guid}/catalog",CustomerCatalog).WithMetadata(new Permission("pricing.read"));
        g.MapGet("/products/{id:guid}/barcodes",async(Guid id,CompanySession s,CancellationToken ct)=>Results.Ok(new{items=(await Read(s,"SELECT b.* FROM catalog.unit_barcodes b JOIN catalog.product_units u ON u.company_id=b.company_id AND u.id=b.product_unit_id WHERE b.company_id=@company AND u.product_id=@id ORDER BY b.barcode,b.id",ct,new DbArg("id",id))).Select(PublicRow)})).WithMetadata(new Permission("catalog.read"));
        g.MapPost("/product-barcodes",Barcode).WithMetadata(new Permission("catalog.write"));
        g.MapPut("/product-barcodes/{id:guid}",async(Guid id,BarcodeStatusInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>
        {
            var version=Version(h);var result=await idem.ExecuteAsync($"PUT /product-barcodes/{id}",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{id,version,input.Active}),async()=>{var before=await One(s,"SELECT * FROM catalog.unit_barcodes WHERE company_id=@company AND id=@id FOR UPDATE",ct,new DbArg("id",id));if((long)before["version"]! !=version)throw new BusinessException("version_conflict","Barcode changed.",409);var row=await One(s,"UPDATE catalog.unit_barcodes SET active=@active WHERE company_id=@company AND id=@id RETURNING *",ct,new DbArg("id",id),new DbArg("active",input.Active));await Sql.AuditAsync(s,"catalog.barcode_changed","product_barcode",id,h.TraceIdentifier,ct,new{input.Active});return ApiJson.Stored(PublicRow(row),200);},ct);return ApiJson.Result(result);
        }).WithMetadata(new Permission("catalog.write"));

        g.MapGet("/settings/business",async(CompanySession s,CancellationToken ct)=>Results.Ok(PublicRow(await One(s,"SELECT p.*,(now() AT TIME ZONE c.timezone)::date::text AS business_date,((now() AT TIME ZONE c.timezone)::date+p.quote_valid_days)::text AS default_quote_expires_on,c.timezone,c.base_currency AS currency FROM core.business_preferences p JOIN core.companies c ON c.id=p.company_id WHERE p.company_id=@company",ct)))).WithMetadata(new Permission("settings.business.read"));
        g.MapPut("/settings/business",async(BusinessPreferencesInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>
        {
            var expected=Version(h);Check.That(input.SalesTermsDays is>=0 and<=365&&input.PurchaseTermsDays is>=0 and<=365&&input.QuoteValidDays is>=1 and<=365,"terms","Terms or quote validity out of range.");var d=input with{DefaultDispatchMode=Check.OneOf(input.DefaultDispatchMode,"defaultDispatchMode","PICKUP","DELIVERY"),Notes=Check.Optional(input.Notes,"notes",2000)??""};var result=await idem.ExecuteAsync("PUT /settings/business",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{expected,d}),async()=>{await Read(s,"SELECT core.configure_business(@version,@sales,@purchase,@quote,@dispatch,@notes)",ct,new DbArg("version",expected),new DbArg("sales",d.SalesTermsDays),new DbArg("purchase",d.PurchaseTermsDays),new DbArg("quote",d.QuoteValidDays),new DbArg("dispatch",d.DefaultDispatchMode),new DbArg("notes",d.Notes));await Sql.AuditAsync(s,"settings.business_changed","business_preferences",s.CompanyId,h.TraceIdentifier,ct,d);return ApiJson.Stored(PublicRow(await One(s,"SELECT * FROM core.business_preferences WHERE company_id=@company",ct)),200);},ct);return ApiJson.Result(result);
        }).WithMetadata(new Permission("settings.business.write"));
        g.MapGet("/settings/document-numbering",async(CompanySession s,CancellationToken ct)=>Results.Ok(new{items=(await Read(s,"SELECT id,document_type,prefix,next_value,version FROM platform.document_sequences WHERE company_id=@company ORDER BY document_type",ct)).Select(PublicRow)})).WithMetadata(new Permission("settings.business.read"));
        g.MapPut("/settings/document-numbering/{type}",async(string type,NumberingInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>
        {
            var expected=Version(h);var prefix=Check.Text(input.Prefix,"prefix",20).ToUpperInvariant();Check.That(input.NextValue is>=1 and<=999999999999&&prefix.All(x=>char.IsAsciiLetterOrDigit(x)||x=='-'||x=='_')&&char.IsAsciiLetterOrDigit(prefix[0]),"prefix","Invalid numbering prefix/counter.");var result=await idem.ExecuteAsync($"PUT /settings/document-numbering/{type}",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{expected,prefix,input.NextValue}),async()=>{await Read(s,"SELECT core.configure_numbering(@type,@version,@prefix,@next)",ct,new DbArg("type",type),new DbArg("version",expected),new DbArg("prefix",prefix),new DbArg("next",input.NextValue));var row=await One(s,"SELECT id,document_type,prefix,next_value,version FROM platform.document_sequences WHERE company_id=@company AND document_type=@type",ct,new DbArg("type",type));await Sql.AuditAsync(s,"settings.numbering_changed","document_sequence",(Guid)row["id"]!,h.TraceIdentifier,ct,new{type,prefix,input.NextValue});return ApiJson.Stored(PublicRow(row),200);},ct);return ApiJson.Result(result);
        }).WithMetadata(new Permission("settings.business.write"));
    }
    private static long Version(HttpContext h){if(!long.TryParse(h.Request.Headers.IfMatch.ToString().Trim('"'),out var v)||v<1)throw new BusinessException("version_required","Current If-Match required.",428);return v;}
    private static async Task<IResult> Products(string? q,string? status,string? sort,bool? descending,int? page,int? pageSize,CompanySession s,CancellationToken ct)
    {
        var text=Query(q);if(status is not null)Check.OneOf(status,"status","ACTIVE","INACTIVE");var(offset,size)=Page(page,pageSize);var order=Order(sort,descending??false,new Dictionary<string,string>{{"sku","sku"},{"name","name"}});var rows=await Read(s,$"SELECT p.id,p.sku,p.name,p.item_type,p.status,p.sell_enabled,p.buy_enabled FROM catalog.products p WHERE p.company_id=@company AND (@status IS NULL OR p.status=@status) AND (@q='' OR strpos(lower(p.sku||' '||p.name),lower(@q))>0 OR EXISTS(SELECT 1 FROM catalog.product_barcodes pb WHERE pb.company_id=p.company_id AND pb.product_id=p.id AND pb.barcode=@q) OR EXISTS(SELECT 1 FROM catalog.product_units u JOIN catalog.unit_barcodes b ON b.company_id=u.company_id AND b.product_unit_id=u.id WHERE u.company_id=p.company_id AND u.product_id=p.id AND b.active AND b.barcode=@q)) ORDER BY {order} LIMIT @size OFFSET @offset",ct,new DbArg("q",text),new DbArg("status",status,NpgsqlDbType.Text),new DbArg("size",size),new DbArg("offset",offset));return Results.Ok(new{items=rows.Select(PublicRow),page=page??1,pageSize=size});
    }
    private static async Task<IResult> CustomerCatalog(Guid customerId,Guid warehouseId,string? q,int? page,int? pageSize,HttpContext h,CompanySession s,CancellationToken ct)
    {
        if(!Access(h).Has("catalog.read")||!Access(h).Has("inventory.read"))throw new BusinessException("permission_denied","Catalog and inventory access required.",403);await Customer(h,s,customerId,ct);await Read(s,"SELECT inventory.require_access('inventory.read',@warehouse)",ct,new DbArg("warehouse",warehouseId));var text=Query(q);var(offset,size)=Page(page,pageSize);
        var rows=await Read(s,"SELECT p.id AS product_id,p.sku,p.name,p.item_type,um.code AS unit_code,bu.code AS base_unit_code,u.id AS product_unit_id,coalesce(b.on_hand,0) AS on_hand,coalesce(b.reserved,0) AS reserved,CASE WHEN w.active AND w.kind='SELLABLE' AND p.item_type='STOCK' THEN greatest(0,coalesce(b.on_hand-b.reserved,0)) ELSE 0 END AS available FROM catalog.products p JOIN catalog.product_units u ON u.company_id=p.company_id AND u.product_id=p.id AND u.active JOIN catalog.uoms um ON um.company_id=u.company_id AND um.id=u.uom_id AND um.active JOIN catalog.uoms bu ON bu.company_id=p.company_id AND bu.id=p.base_uom_id JOIN catalog.warehouses w ON w.company_id=p.company_id AND w.id=@warehouse LEFT JOIN inventory.stock_balances b ON b.company_id=p.company_id AND b.product_id=p.id AND b.warehouse_id=w.id WHERE p.company_id=@company AND p.status='ACTIVE' AND p.sell_enabled AND (@q='' OR strpos(lower(p.sku||' '||p.name),lower(@q))>0 OR EXISTS(SELECT 1 FROM catalog.product_barcodes pb WHERE pb.company_id=p.company_id AND pb.product_id=p.id AND pb.barcode=@q) OR EXISTS(SELECT 1 FROM catalog.unit_barcodes bc WHERE bc.company_id=u.company_id AND bc.product_unit_id=u.id AND bc.active AND bc.barcode=@q)) ORDER BY p.sku,u.id LIMIT @size OFFSET @offset",ct,new DbArg("warehouse",warehouseId),new DbArg("q",text),new DbArg("size",size),new DbArg("offset",offset));var now=DateTimeOffset.UtcNow;var items=new List<object>();foreach(var row in rows){object? price=null;string? code=null;try{price=(await QuotePricing.Resolve(s,customerId,(Guid)row["product_unit_id"]!,now,ct)).Public(customerId,(Guid)row["product_unit_id"]!);}catch(BusinessException e)when(e.StatusCode is 404 or 409 or 422){code=e.Code;}items.Add(new{product=PublicRow(row),price,priceUnavailableCode=code});}return Results.Ok(new{customerId,warehouseId,items,page=page??1,pageSize=size,dataAsOf=now});
    }
    private static async Task<IResult> Barcode(BarcodeInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
    {
        var code=Check.Text(input.Barcode,"barcode",80);Check.That(code.All(x=>x is>= '!' and<= '~')&&!code.StartsWith("BIN:",StringComparison.OrdinalIgnoreCase)&&!code.StartsWith("LOT:",StringComparison.OrdinalIgnoreCase),"barcode","Printable ASCII barcode required.");await One(s,"SELECT id FROM catalog.product_units WHERE company_id=@company AND id=@unit",ct,new DbArg("unit",input.ProductUnitId));var result=await idem.ExecuteAsync("POST /product-barcodes",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{input.ProductUnitId,barcode=code,input.Active}),async()=>{var row=await One(s,"INSERT INTO catalog.unit_barcodes(company_id,product_unit_id,barcode,active,created_by) VALUES(@company,@unit,@barcode,@active,@actor) RETURNING *",ct,new DbArg("unit",input.ProductUnitId),new DbArg("barcode",code),new DbArg("active",input.Active));await Sql.AuditAsync(s,"catalog.barcode_created","product_barcode",(Guid)row["id"]!,h.TraceIdentifier,ct,new{input.ProductUnitId,barcode=code});return ApiJson.Stored(PublicRow(row));},ct);return ApiJson.Result(result);
    }
}
